/*
 * Pasa la salida de SQL Server a los nombres de columna de Postgres.
 *
 * Las fechas se formatean SIEMPRE con getters UTC. El flujo viejo mezclaba
 * `toISOString()` para la fecha con `toLocaleTimeString()` para la hora, que usa
 * la zona del servidor: cerca de medianoche las dos mitades se contradecían.
 */
const fecha = (v) => (v ? new Date(v).toISOString().slice(0, 10) : null);
const texto = (v) => {
  const t = String(v ?? '').trim();
  return t === '' || t.toLowerCase() === 'null' ? null : t;
};

return $input.all().map(({ json: r }) => ({
  json: {
    id: Number(r.Id),
    fecha_creacion: fecha(r.FechaCreacion),
    fecha_programado: fecha(r.FechaProgramado),
    estado: texto(r.Estado),
    repartidor: texto(r.Repartidor),
    tienda: texto(r.Tienda),
    destino: texto(r.Destino),
    poligono: texto(r.Poligono),
    visitas: Number.isFinite(Number(r.Visitas)) ? Number(r.Visitas) : null,
  },
})).filter((i) => Number.isFinite(i.json.id) && i.json.id > 0);

