/*
 * Cancelados a columnas de la base.
 *
 * Las dos fechas ya vienen con las 3 horas restadas por la consulta, así que son
 * hora local de México. Se formatean con getters UTC para conservar exactamente
 * ese reloj de pared: la columna en Postgres es `timestamp` sin zona, y aplicar
 * una segunda conversión las correría de nuevo.
 */
const marca = (v) => (v ? new Date(v).toISOString().slice(0, 19).replace('T', ' ') : null);
const texto = (v) => {
  const t = String(v ?? '').trim();
  return t === '' || t.toLowerCase() === 'null' ? null : t;
};

return $input.all().map(({ json: r }) => ({
  json: {
    id: Number(r.Id),
    id_meli: texto(r.Id_MELI),
    tienda: texto(r.Tienda),
    estado_rbp: texto(r.Estado_RBP),
    estado_meli: texto(r.Estado_MELI),
    fecha_colectado: marca(r.Fecha_Colectado),
    fecha_cancelado: marca(r.Fecha_Cancelado),
  },
})).filter((i) => Number.isFinite(i.json.id) && i.json.id > 0);
